using CustomCodeFramework.Cqrs.Queries;using Dhole.Content.Application.Abstractions.Cache;using Dhole.Content.Application.Abstractions.Repositories;using Dhole.Content.Application.Mappings;using Dhole.Content.Contracts.Settings;using Dhole.Content.Domain.Shared;namespace Dhole.Content.Application.Settings.GetSiteSettings;public sealed class GetSiteSettingsQueryHandler(ISiteSettingRepository repo,IContentCacheService cache):IQueryHandler<GetSiteSettingsQuery,IReadOnlyCollection<SiteSettingDto>>{public async Task<IReadOnlyCollection<SiteSettingDto>> HandleAsync(GetSiteSettingsQuery q,CancellationToken ct=default){var site=string.IsNullOrWhiteSpace(q.SiteKey)?ContentConstants.DefaultSiteKey:q.SiteKey.Trim();if(q.PublicOnly){var cached=await cache.GetPublicSettingsAsync(site,ct);if(cached is not null)return cached;}var values=(await repo.GetBySiteAsync(site,q.PublicOnly,ct)).Select(ContentMappings.ToDto).ToArray();if(q.PublicOnly)await cache.SetPublicSettingsAsync(site,values,cancellationToken:ct);return values;}}
